  if (text.isEmpty) return [''];
  final out = <String>[];
  for (final paragraph in text.split('\n')) {
    if (paragraph.isEmpty) {
      out.add('');
      continue;
    }
    out.addAll(_wrapCells(paragraph, width));
  }
